---InitConstants 初始化游戏内的常量
local function InitConstants()
	local constantsMap = {}

	for _, filePath in ipairs(constantsFile) do
		for k, v in pairs(import(filePath)) do
			if constantsMap[k] == nil then
				constantsMap[k] = v
